  'sh.test.accounting.title': "अपने अकाउंटिंग सॉफ़्टवेयर की एक टेस्ट रीडिंग चलाएं",
  'sh.test.accounting.how': "एक रीडिंग, जैसा अभी पढ़ें करता है। उसके बाद, कोई {account_l} खोलें और उसके खुले इनवॉइस सॉफ़्टवेयर से मिलाएं।",
  'demo.tour.setup-check.title': "अपना सेटअप जांचें और टेस्ट करें",
