  'trialMail.approved.body': "नमस्ते {name},\n\nअच्छी खबर: {company} के लिए आपका Curahold ट्रायल तैयार है। इसमें {seats} लोगों की जगह है और यह {until} तक चलेगा।\n\nअपनी कंपनी सेट अप करने के लिए इस लिंक से साइन इन करें। यह एक बार, 7 दिनों तक काम करता है:\n\n{link}\n\nअंदर पहुंचने के बाद, सेटअप प्लान आपको अपनी टीम को आमंत्रित करने और अपने टूल कनेक्ट करने में मदद करता है। कोई सवाल हो तो बस इस ईमेल का जवाब दें।\n\nCurahold टीम",
