  'trialMail.rejected.body': "नमस्ते {name},\n\nCurahold में आपकी रुचि और {company} के बारे में बताने के लिए समय निकालने के लिए धन्यवाद।\n\nहम अभी इस अनुरोध के लिए ट्रायल शुरू नहीं कर सकते। यह आपकी टीम के बारे में कोई राय नहीं है: हम ट्रायल धीरे-धीरे खोलते हैं, ताकि हर कंपनी को पहले दिन से सही मदद मिले।\n\nहम आपकी जानकारी रखेंगे और जब कोई उपयुक्त ट्रायल दे सकेंगे, तो संपर्क करेंगे। अगर आपकी तरफ़ कुछ बदलता है, तो बस इस ईमेल का जवाब दें।\n\nसादर,\nCurahold टीम",
