  'fin.steps.zohobooks': "उस Zoho अकाउंट से साइन इन करें जो आपका Zoho Books संगठन देख सकता है।\nCurahold को संपर्क, इनवॉइस और भुगतान पढ़ने की अनुमति दें। यह सिर्फ़ पढ़ने का एक्सेस मांगता है।\nयहां वापस आकर, पहली रीडिंग शुरू करें और जिन ग्राहकों का मिलान नहीं हो सका उन्हें जांचें।",
  'fin.steps.xero': "Xero में साइन इन करें और कनेक्ट करने के लिए संगठन चुनें।\nसंपर्क और लेन-देन पढ़ने की अनुमति दें; Curahold Xero में कुछ भी नहीं बदल सकता।\nयहां वापस आकर, पहली रीडिंग शुरू करें और जिन ग्राहकों का मिलान नहीं हो सका उन्हें जांचें।",
  'fin.steps.freee': "freee में साइन इन करें और कनेक्ट करने के लिए कंपनी (事業所) चुनें।\nएक्सेस की अनुमति दें; Curahold सिर्फ़ पार्टनर और सेल्स डील पढ़ता है।\nयहां वापस आकर, पहली रीडिंग शुरू करें और जिन ग्राहकों का मिलान नहीं हो सका उन्हें जांचें।",
  'fin.steps.quickbooks': "Intuit में साइन इन करें और कनेक्ट करने के लिए QuickBooks कंपनी चुनें।\nअकाउंटिंग डेटा के एक्सेस की अनुमति दें; Curahold सिर्फ़ ग्राहक, इनवॉइस और भुगतान पढ़ता है।\nयहां वापस आकर, पहली रीडिंग शुरू करें और जिन ग्राहकों का मिलान नहीं हो सका उन्हें जांचें।",
  'fin.steps.odoo': "Odoo में, अपनी प्रोफ़ाइल → Preferences → Account Security खोलें और एक API key बनाएं।\nअपना Odoo पता और अपना लॉगिन नोट करें। Odoo.sh या अपने सर्वर पर, डेटाबेस का नाम भी।\nइन्हें नीचे डालें। Odoo Online पर API एक्सेस के लिए Custom प्लान चाहिए (Odoo का नियम)।",
  'fin.steps.parasut': "अपनी कंपनी के लिए API एक्सेस के लिए Paraşüt सपोर्ट से कहें; वे एक client ID और client secret भेजते हैं।\nआपका कंपनी नंबर एड्रेस बार में uygulama.parasut.com/ के बाद है।\nइन्हें किसी Paraşüt यूज़र के ईमेल और पासवर्ड के साथ डालें। पासवर्ड एक बार की पाने के लिए इस्तेमाल होता है और रखा नहीं जाता।",
  'fin.steps.finfile': "अपने सॉफ़्टवेयर से ग्राहक, इनवॉइस और भुगतान Excel या CSV के रूप में एक्सपोर्ट करें।\nउन्हें टेम्पलेट के कॉलम में रखें; अगली स्क्रीन पर आप टेम्पलेट डाउनलोड कर सकते हैं।\nपहले ग्राहक, फिर इनवॉइस, फिर भुगतान अपलोड करें। जब भी नए आंकड़े चाहिए, नई फ़ाइल अपलोड करें।",
