  'imp.leadBoard': "पहले इस्तेमाल किए गए टूल से अपने टास्क एक्सपोर्ट करें (CSV, Excel, या किसी बोर्ड का JSON एक्सपोर्ट) और फ़ाइल यहां छोड़ें; वे “{board}” पर, या आपके चुने बोर्ड पर आएंगे। कुछ भी सेव होने से पहले आप देखते हैं कि क्या आएगा।",
