  'imp.privacy': "आपकी फ़ाइल यहीं, आपके ब्राउज़र में पढ़ी जाती है। जब तक आप “लाएं” न दबाएं, कुछ सेव नहीं होता, और किसी को सूचना नहीं जाती।",
  'imp.privacyDemo': "यह डेमो पूरी तरह आपके ब्राउज़र टैब में चलता है: आपकी फ़ाइल कभी आपके डिवाइस से बाहर नहीं जाती। कुछ भी अपलोड नहीं होता, और पेज रीलोड करने पर यह भूल जाती है।",
