  'demo.tour.onboarding-hub.title': "आपका शुरुआत का प्लान",
  'demo.tour.onboarding-hub.blurb': "एक साझा प्लान: आगे का काम, किसकी बारी है, अपने आप टिक होने वाले स्टेप, साझा इश्यू और डेटा जांच।",
  'demo.tour.onboarding-hub.1.title': "आगे करने का एक काम",
  'demo.tour.onboarding-hub.1.body': "हमेशा सबसे ऊपर: अगला खुला स्टेप, किसकी बारी है और कब से, और एक बटन जो आपको वहां ले जाता है।",
  'demo.tour.onboarding-hub.2.title': "वेटेड प्रगति",
  'demo.tour.onboarding-hub.2.body': "ज़रूरी स्टेप पूरे गिने जाते हैं, वैकल्पिक आधे। बिंदु बताता है कि आज तक कितना अपेक्षित था, और काउंटर बताते हैं कि किसका इंतज़ार है।",
  'demo.tour.onboarding-hub.3.title': "अपने आप टिक होने वाले स्टेप",
  'demo.tour.onboarding-hub.3.body': "टीम को आमंत्रित करना, एक इंपोर्ट, ठीक से चला एक कनेक्शन: Curahold इन्हें देखता है और स्टेप टिक कर देता है। लॉक किया गया स्टेप बताता है कि वह किसका इंतज़ार कर रहा है।",
  'demo.tour.onboarding-hub.4.title': "साझा इश्यू",
  'demo.tour.onboarding-hub.4.body': "हर एक बताता है कि बारी किसकी है। फ़ेल हुआ सेटअप टेस्ट यहां एक पंक्ति है, फिर से टेस्ट करने के बटन के साथ; इश्यू एक सपोर्ट टिकट हो सकता है, उसकी कॉपी कभी नहीं।",
  'demo.tour.onboarding-hub.5.title': "अपेक्षित और मिला",
  'demo.tour.onboarding-hub.5.body': "हर मैप किया गया फ़ील्ड चार नियमों पर परखा जाता है: प्रकार, फ़ॉर्मैट, ज़रूरी और खाली। ठीक की गई पंक्ति तुरंत फ़ेल सूची से निकल जाती है।",
  'demo.tour.onboarding-hub.6.title': "हर भूमिका के लिए एक व्यू",
  'demo.tour.onboarding-hub.6.body': "प्रोजेक्ट लीड सब कुछ देखते हैं, स्पॉन्सर सारांश, तकनीकी ओनर स्टेप, डेटा और इश्यू। रिपोर्ट को सिर्फ़ पढ़ने वाले लिंक के रूप में शेयर करें या प्रिंट करें।",
  'demo.tour.onboarding-hub.7.title': "आपके ग्राहकों के प्लान",
  'demo.tour.onboarding-hub.7.body': "वही प्लान, आपकी हर ग्राहक ऑनबोर्डिंग के लिए: जीती डील से खुलता है, ग्राहक इसे आपके पोर्टल में देखता है, और सभी पर अटकने के संकेत होते हैं।",
