  "errors.crm_unreachable": "हम उस पते तक नहीं पहुंच सके। जांचें कि नाम सही लिखा है; अगर है, तो हो सकता है आपकी कंपनी का नेटवर्क इसे ब्लॉक कर रहा हो: अपनी IT टीम से पूछें।",
  "sync.removeBodyAccounting": "पढ़ना बंद हो जाता है। {app} से पढ़े गए बैलेंस, इनवॉइस और भुगतान ग्राहकों के पेज से हट जाते हैं; ग्राहक खुद बने रहते हैं। {app} में कुछ नहीं बदलता।",
