  "assist.settings.offNotice": "जब तक कोई एडमिन AI जवाब चालू नहीं करता, वे बंद रहते हैं। चालू होने पर हर सवाल और उसका जवाब देने के लिए ज़रूरी न्यूनतम संदर्भ हमारे AI प्रोवाइडर (सब-प्रोसेसर में सूचीबद्ध) को जाता है। किसी भी चीज़ का इस्तेमाल AI मॉडल को ट्रेन करने के लिए नहीं होता।",
  "assistConsent.title": "AI असिस्टेंट से पूछने से पहले",
  "assistConsent.what": "आपका सवाल, इस चैट के आखिरी कुछ मैसेज और जवाब देने के लिए ज़रूरी न्यूनतम संदर्भ (ऐप में: आपका नाम, आपकी भूमिका और वे रिकॉर्ड जो आप पहले से देख सकते हैं) हमारे AI मॉडल प्रोवाइडर को भेजे जाते हैं, जो सब-प्रोसेसर में सूचीबद्ध है और आपके देश से बाहर हो सकता है।",
  "assistConsent.why": "इसका एकमात्र उद्देश्य आपको जवाब देना है। किसी भी चीज़ का इस्तेमाल AI मॉडल को ट्रेन करने के लिए नहीं होता।",
  "assistConsent.keep": "सवाल उतने ही समय तक रखे जाते हैं जितना आपकी कंपनी ने चुना है (जब तक बदला न गया हो, 30 दिन; सार्वजनिक डॉक्स से कोई नहीं), फिर हटा दिए जाते हैं।",
  "assistConsent.withdraw": "आप अभी मना कर सकते हैं या बाद में, यहां या आपकी सेटिंग में, सहमति वापस ले सकते हैं, और आपका कुछ नहीं खोता: डॉक्स सर्च आपके डिवाइस पर जवाब देता रहता है।",
