  "whatsapp.cost": "हर मैसेज आपके अपने Meta अकाउंट से जाता है और उसका बिल Meta आपको भेजता है। ग्राहक के आख़िरी मैसेज के 24 घंटे के अंदर जवाब में कुछ भी लिखा जा सकता है; उसके बाद WhatsApp सिर्फ़ वही टेम्पलेट स्वीकार करता है जिसे आपने मंज़ूर करवाया हो।",
  "whatsapp.reply.action": "WhatsApp पर जवाब दें",
