  "whatsapp.reply.window": "इस ग्राहक के आख़िरी मैसेज को 24 घंटे से ज़्यादा हो चुके हैं। अब WhatsApp सिर्फ़ मंज़ूर टेम्पलेट स्वीकार करता है: उसका नाम और भाषा दर्ज करें।",
