  "devtools.hook.secretAzure": "पासवर्ड (Azure DevOps: Basic authentication पासवर्ड; कोई भी यूज़र नेम)",
  "devtools.hook.eventsAzure": "Azure DevOps में: Project settings → Service hooks → + → Web Hooks। इस पते के साथ Code pushed, Pull request created, Pull request updated, Pull request merge attempted और Build completed के लिए एक-एक सब्सक्रिप्शन बनाएं।",
  "hooks.title": "इनकमिंग वेबहुक",
  "hooks.lede": "हर उस टूल के लिए जो किसी वेब पते को कॉल कर सकता है: ई-सिग्नेचर, फ़ोन, चैट, भुगतान, Zapier, Make या आपका अपना कोड। हर डिलीवरी एक टास्क, एक टिकट, ग्राहक पर एक एंट्री या डील पर एक नोट बन जाती है; वही आइटम दोबारा भेजा जाए तो वह अपडेट हो जाता है।",
