  "hooks.how.curahold": "Zapier में “Webhooks by Zapier → POST” और Make में “HTTP → Make a request” इस्तेमाल करें। बॉडी पर हस्ताक्षर करें: X-Curahold-Signature: t=<unix seconds>,v1=<सीक्रेट के साथ \"t.body\" का hex HMAC-SHA256>। X-Curahold-Event-Id जोड़ें ताकि दोबारा भेजा गया इवेंट सिर्फ़ एक बार इस्तेमाल हो।",
  "hooks.how.esign": "DocuSign में: Settings → Connect → Add Configuration → Custom। पते को URL to publish to में पेस्ट करें, JSON चुनें, Envelope Sent, Completed, Declined और Voided पर टिक करें, और यहां लिखी की के साथ HMAC चालू करें।",
  "hooks.how.aircall": "Aircall में: Integrations → Webhook → Install। पता पेस्ट करें, call.ended पर टिक करें, और वेबहुक का टोकन यहां पेस्ट करें।",
  "hooks.how.tawkto": "Tawk.to में: Administration → Settings → Webhooks → Create webhook। पता पेस्ट करें, Chat end और Ticket create पर टिक करें, और उसकी सीक्रेट की यहां पेस्ट करें।",
  "hooks.how.razorpay": "Razorpay में: Accounts & Settings → Webhooks → Add New Webhook। पता पेस्ट करें, एक सीक्रेट लिखें (यहां भी वही), payment.captured और payment.failed पर टिक करें।",
  "hooks.how.custom": "पते पर JSON भेजें, सीक्रेट को X-Curahold-Token हेडर में रखें (या अगर टूल हेडर सेट नहीं कर सकता तो पते में ?टोकन= लगाएं)।",
  "hooks.url": "टूल को देने वाला पता",
  "hooks.secret": "सीक्रेट",
  "hooks.senderSet": "टूल का अपना सीक्रेट सेव हो गया है (यह दोबारा कभी नहीं दिखाया जाएगा)।",
  "hooks.senderMissing": "टूल का सीक्रेट अभी सेट नहीं है: जब तक यह सेट नहीं होता, टूल का भेजा कुछ भी इस्तेमाल नहीं होगा।",
  "hooks.scheme.curahold": "जांच: हस्ताक्षर, 5 मिनट के अंदर का समय, और हर इवेंट सिर्फ़ एक बार।",
  "hooks.scheme.hmac": "जांच: टूल का अपना हस्ताक्षर हेडर, उसका समय (अगर वह भेजता है), और हर इवेंट सिर्फ़ एक बार।",
  "hooks.scheme.token": "जांच: साझा टोकन, और हर इवेंट सिर्फ़ एक बार। जहां टूल हस्ताक्षर का विकल्प देता है, वहां हस्ताक्षर इस्तेमाल करें।",
  "hooks.pause": "रोकें",
