  "hooks.rotate": "नया सीक्रेट",
  "hooks.rotated": "नया सीक्रेट सेट हो गया है; पुराना अब से काम नहीं करेगा।",
  "hooks.remove": "वेबहुक हटाएं",
  "hooks.removeBody": "पता तुरंत बंद हो जाएगा और लॉग मिटा दिया जाएगा। इसने जो बनाया (टास्क, टिकट, एंट्री) वह बना रहेगा।",
  "hooks.map.lede": "हर वैल्यू को टेक्स्ट के रूप में लिखें; डिलीवरी की किसी वैल्यू को उसके पाथ के साथ डबल कर्ली ब्रैकेट में रखें (टेस्ट टैब पर प्रीव्यू के बाद सूची से चुनें)। ग्राहक पहले किसी संपर्क के ईमेल से, फिर वेब पते से, फिर नाम से ढूंढा जाता है।",
