  "hooks.why.bad_signature": "अस्वीकार: सिग्नेचर secret से मेल नहीं खाता। “पता” टैब से secret भेजने वाले टूल में कॉपी करें।",
  "hooks.why.bad_token": "अस्वीकार: token नहीं है या ग़लत है। “पता” टैब से secret भेजने वाले टूल में कॉपी करें।",
  "hooks.why.too_old": "अस्वीकार: बहुत पहले भेजा गया, या भेजने वाले टूल की घड़ी ग़लत है। दोबारा भेजी गई पुरानी डिलीवरी इसी तरह अस्वीकार होती है।",
  "hooks.why.no_secret": "अस्वीकार: टूल का अपना secret अभी सेव नहीं हुआ है। उसे “पता” टैब में पेस्ट करें।",
  "hooks.why.not_json": "अस्वीकार: बॉडी न JSON है, न फ़ॉर्म फ़ील्ड।",
  "hooks.why.owner_gone": "इस्तेमाल नहीं हुआ: यह वेबहुक सेट करने वाला व्यक्ति जा चुका है। इसे फिर से सेट करें।",
  "hooks.why.not_used": "छोड़ा गया: “{value}” उन मानों में नहीं है जिन्हें यह वेबहुक इस्तेमाल करता है।",
  "hooks.why.unknown_target": "विफल: हर डिलीवरी क्या बनेगी, यह पता नहीं है। इस वेबहुक को हटाकर फिर से जोड़ें।",
  "hooks.why.no_board": "विफल: बोर्ड हटा दिया गया है या पहुँच से बाहर है। “मैपिंग” टैब में “बोर्ड” से दूसरा बोर्ड चुनें।",
  "hooks.why.no_title": "विफल: “टाइटल” ख़ाली निकला। इसे “मैपिंग” टैब में जाँचें।",
  "hooks.why.no_subject": "विफल: “विषय” ख़ाली निकला। इसे “मैपिंग” टैब में जाँचें।",
  "hooks.why.no_customer": "विफल: इस डिलीवरी से कोई ग्राहक मेल नहीं खाता (किसी संपर्क के ईमेल, डोमेन या नाम से)।",
  "hooks.why.no_body": "विफल: “टेक्स्ट” ख़ाली निकला। इसे “मैपिंग” टैब में जाँचें।",
  "hooks.why.no_deal": "विफल: इस डिलीवरी से कोई डील मेल नहीं खाती।",
  "hooks.why.not_written": "विफल: एंट्री सेव नहीं हो सकी। टूल से डिलीवरी फिर से भेजें।",
  "hooks.why.other": "विफल। डिलीवरी यहाँ रखी गई है ताकि आप देख सकें कि क्या आया।",
